// shared/input/InputController.ts
import * as THREE from 'three';

export class InputController {
    keys = new Set<string>();
    gamepadIndex: number | null = null;

    constructor() {
        window.addEventListener('keydown', e => this.keys.add(e.code));
        window.addEventListener('keyup', e => this.keys.delete(e.code));

        // Gamepad polling setup
        setInterval(() => {
            const gps = navigator.getGamepads();
            for (let i=0; i<gps.length; i++) {
                if (gps[i]) { this.gamepadIndex = i; break; }
            }
        }, 100);
    }

    isDown(code: string): boolean { return this.keys.has(code); }

    getAxis(axis: 'left' | 'right'): number {
        if (this.gamepadIndex !== null) {
            const gp = navigator.getGamepads()[this.gamepadIndex];
            // Standard mapping: 0=LeftStickX, 2=RightStickX
            return gp.axes[0] || 0; 
        }
        let val = 0;
        if (this.isDown('ArrowLeft') || this.isDown('KeyA')) val -= 1;
        if (this.isDown('ArrowRight') || this.isDown('KeyD')) val += 1;
        return val;
    }

    getTrigger(): boolean {
        if (this.gamepadIndex !== null) {
            const gp = navigator.getGamepads()[this.gamepadIndex];
            return gp.buttons[0]?.pressed || false; // A button / Cross
        }
        return this.isDown('Space') || this.isDown('Enter');
    }
}
