import * as THREE from 'three';
import { Vec3 } from '../types.js';

export interface ParticleData {
    pos: Vec3; vel: Vec3; life: number; maxLife: number; color: THREE.Color; active: boolean;
}

const MAX_PARTICLES = 500;

export class ParticleManager {
    particles: ParticleData[] = [];
    mesh: THREE.InstancedMesh | null = null;

    constructor(scene: THREE.Scene) {
        const geo = new THREE.SphereGeometry(0.1, 4, 4); // Low poly for perf
        const mat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        this.mesh = new THREE.InstancedMesh(geo, mat, MAX_PARTICLES);

        for(let i=0; i<MAX_PARTICLES; i++) {
            this.particles.push({ pos:{x:0,y:0,z:0}, vel:{x:0,y:0,z:0}, life:0, maxLife:0, color:new THREE.Color(), active:false });
        }
        scene.add(this.mesh);
    }

    spawn(x:number, y:number, z:number, vx:number, vy:number, vz:number, r:number, g:number, b:number, count=1) {
        let spawned = 0;
        for(let i=0; i<MAX_PARTICLES && spawned<count; i++) {
            if(!this.particles[i].active) {
                const p = this.particles[i];
                p.active = true;
                p.pos = {x,y,z};
                p.vel = {x:vx + (Math.random()-0.5)*2, y:vy + (Math.random()-0.5)*2, z:vz + (Math.random()-0.5)*2};
                p.life = 0.6 + Math.random() * 0.6; // 0.6-1.2s
                p.maxLife = p.life;
                p.color.setRGB(r, g, b);
                spawned++;
            }
        }
    }

    update(dt: number) {
        let i = 0;
        for(const p of this.particles) {
            if(!p.active) continue;
            p.life -= dt;
            if(p.life <= 0) { p.active = false; continue; }

            // Physics
            p.pos.x += p.vel.x * dt;
            p.pos.y += p.vel.y * dt;
            p.pos.z += p.vel.z * dt;
            p.vel.y -= 9.8 * dt; // Gravity

            const alpha = Math.max(0, p.life / p.maxLife);

            if(i < this.mesh!.count) {
                const m = new THREE.Matrix4().setPosition(p.pos.x, p.pos.y, p.pos.z).scale(new THREE.Vector3(alpha, alpha, alpha));
                this.mesh!.setMatrixAt(i, m);
                this.mesh!.setColorAt(i, p.color);
            }
            i++;
        }
        this.mesh!.instanceMatrix.needsUpdate = true;
        if(this.mesh!.instanceColor) this.mesh!.instanceColor!.needsUpdate = true;
    }
}
