// shared/vfx/CameraShake.ts
export class CameraShake {
    trauma: number = 0;
    decay: number = 0.95;

    addImpact(intensity: number) { this.trauma = Math.min(1, this.trauma + intensity); }

    update(dt: number): {x:number, y:number} {
        if(this.trauma < 0.01) return {x:0, y:0};

        this.trauma *= Math.pow(this.decay, dt * 60);
        const freq = 14;
        const x = Math.sin(Date.now() / (1000/freq)) * this.trauma * 0.3;
        const y = Math.cos(Date.now() / (1000/freq) * 1.3) * this.trauma * 0.2; // Slight vertical offset

        return {x, y};
    }
}
