// game/space_invaders/Entities.ts
import * as THREE from 'three';
import { Vec3 } from '../../shared/types.js';

export class PlayerShip {
    mesh: THREE.Group;
    pos = new THREE.Vector3(0, 0, -10);
    speed = 12;

    constructor() {
        this.mesh = new THREE.Group();

        // Body
        const bodyGeo = new THREE.ConeGeometry(0.5, 1.5, 4);
        bodyGeo.rotateX(Math.PI / 2);
        const bodyMat = new THREE.MeshStandardMaterial({ color: 0x00ffff, emissive: 0x0088ff, emissiveIntensity: 0.5 });
        this.mesh.add(new THREE.Mesh(bodyGeo, bodyMat));

        // Thruster Glow
        const glowGeo = new THREE.SphereGeometry(0.2, 8, 8);
        const glowMat = new THREE.MeshBasicMaterial({ color: 0x00ffff });
        const glow = new THREE.Mesh(glowGeo, glowMat);
        glow.position.z = 0.8;
        this.mesh.add(glow);

        this.mesh.position.copy(this.pos);
    }

    update(dt: number, inputX: number) {
        this.pos.x += inputX * this.speed * dt;
        // Clamp to arena width (-25 to 25)
        this.pos.x = Math.max(-24, Math.min(24, this.pos.x));

        this.mesh.position.copy(this.pos);
    }
}

export class Alien {
    mesh: THREE.Mesh;
    id: number;

    constructor(type: 'A'|'B'|'C', x: number, z: number) {
        let geo: THREE.BufferGeometry;
        let color = 0xffffff;

        if (type === 'A') { // Octahedron
            geo = new THREE.OctahedronGeometry(0.6);
            color = 0xff00ff; // Magenta
        } else if (type === 'B') { // Icosahedron
            geo = new THREE.IcosahedronGeometry(0.5);
            color = 0x00ff00; // Green
        } else { // Tetrahedron
            geo = new THREE.TetrahedronGeometry(0.6);
            color = 0xffff00; // Yellow
        }

        const mat = new THREE.MeshStandardMaterial({ 
            color: color, 
            emissive: color, 
            emissiveIntensity: 0.8,
            wireframe: true 
        });

        this.mesh = new THREE.Mesh(geo, mat);
        this.mesh.position.set(x, 0, z);
        this.id = Math.random();
    }

    update(dt: number, time: number) {
        // "Breathing" animation
        const scale = 1 + Math.sin(time * 3 + this.id * 10) * 0.05;
        this.mesh.scale.set(scale, scale, scale);

        // Slight bobbing
        this.mesh.position.y = Math.sin(time * 2 + this.id * 5) * 0.1;
    }
}

export class Shield {
    segments: THREE.Mesh[] = [];

    constructor(x: number, z: number) {
        const geo = new THREE.BoxGeometry(0.8, 0.8, 0.4);
        const mat = new THREE.MeshStandardMaterial({ color: 0x00ffaa, emissive: 0x00ffaa, emissiveIntensity: 0.5 });

        // Create a small grid of segments (3x3) for destructibility
        for(let i=-1; i<=1; i++) {
            for(let j=-1; j<=1; j++) {
                const seg = new THREE.Mesh(geo, mat.clone());
                seg.position.set(x + i*0.9, 0, z + j*0.9);
                this.segments.push(seg);
            }
        }
    }

    addGroup(group: THREE.Group) { 
        for(const s of this.segments) group.add(s); 
    }

    takeHit(segmentIndex: number) {
        if(this.segments[segmentIndex]) {
            const seg = this.segments[segmentIndex];
            // Remove from parent
            if(seg.parent) seg.parent.remove(seg);
            seg.geometry.dispose();
            seg.material.dispose();
            this.segments[segmentIndex] = null as any;
        }
    }
}

export class UFO {
    mesh: THREE.Group;
    active = false;
    x = 0;

    constructor() {
        this.mesh = new THREE.Group();
        const geo = new THREE.CylinderGeometry(0.5, 1, 0.4, 8);
        const mat = new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 1 });
        this.mesh.add(new THREE.Mesh(geo, mat));

        // Dome
        const domeGeo = new THREE.SphereGeometry(0.4, 8, 4, 0, Math.PI*2, 0, Math.PI/2);
        const domeMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const dome = new THREE.Mesh(domeGeo, domeMat);
        dome.position.y = 0.2;
        this.mesh.add(dome);

        this.mesh.visible = false;
    }

    activate(x: number) {
        this.active = true;
        this.x = x;
        this.mesh.position.set(x, -8, -90); // Top of screen
        this.mesh.visible = true;
    }

    update(dt: number) {
        if(!this.active) return;
        this.x += dt * 15; // Move right
        this.mesh.position.x = this.x;

        // Pulse light
        const pulse = Math.sin(Date.now() / 100) * 0.5 + 0.5;
        this.mesh.children[0].material.emissiveIntensity = 0.5 + pulse;
    }
}
