// game/space_invaders/GameLogic.ts
import * as THREE from 'three';
import { PlayerShip, Alien, Shield, UFO } from './Entities.js';
import { InputController } from '../../shared/input/InputController.js';
import { ParticleManager } from '../../shared/vfx/ParticleManager.js';
import { CameraShake } from '../../shared/vfx/CameraShake.js';

export class GameLogic {
    player: PlayerShip;
    aliens: Alien[] = [];
    shields: Shield[] = [];
    ufo: UFO;

    formationX = -20;
    formationZ = -60;
    formationDir = 1; // 1 = right, -1 = left
    speedMultiplier = 1.0;

    projectiles: { mesh: THREE.Mesh; active: boolean; vel: THREE.Vector3 }[] = [];
    enemyProjectiles: { mesh: THREE.Mesh; active: boolean; vel: THREE.Vector3 }[] = [];

    score = 0;
    lives = 3;
    wave = 1;

    input: InputController;
    particles: ParticleManager;
    shake: CameraShake;

    // Timers
    ufoTimer = 0;
    ufoInterval = 45; // seconds

    constructor(input: InputController, particles: ParticleManager, shake: CameraShake) {
        this.input = input;
        this.particles = particles;
        this.shake = shake;

        this.player = new PlayerShip();
        this.ufo = new UFO();

        this.initWave();
    }

    initWave() {
        // Clear old aliens
        for(const a of this.aliens) if(a.mesh.parent) a.mesh.parent.remove(a.mesh);
        this.aliens = [];

        const rows = 5;
        const cols = 11;
        const startX = -20;
        const startZ = -60 + (this.wave * 2); // Start closer each wave

        for(let r=0; r<rows; r++) {
            for(let c=0; c<cols; c++) {
                let type: 'A'|'B'|'C' = 'C';
                if(r < 1) type = 'A';
                else if(r < 3) type = 'B';

                const alien = new Alien(type, startX + c * 2, startZ);
                this.aliens.push(alien);
            }
        }

        // Reset formation pos
        this.formationX = -20;
        this.speedMultiplier = 1.0 + (this.wave * 0.1);
    }

    update(dt: number, time: number) {
        // Player Movement
        const inputX = this.input.getAxis('left');
        this.player.update(dt, inputX);

        // UFO Logic
        if(!this.ufo.active) {
            this.ufoTimer += dt;
            if(this.ufoTimer > this.ufoInterval) {
                this.ufo.activate(-30 + Math.random() * 60);
                this.ufoTimer = 0;
                this.ufoInterval = 30 + Math.random() * 40;
            }
        } else {
            this.ufo.update(dt);
            if(this.ufo.x > 35) this.ufo.active = false; // Despawn off screen
        }

        // Alien Formation Movement
        let hitEdge = false;
        for(const a of this.aliens) {
            a.mesh.position.x += 0.5 * this.speedMultiplier * this.formationDir * dt;
            if(a.mesh.position.x > 24 || a.mesh.position.x < -24) hitEdge = true;

            // Alien "Breathing" & Bobbing
            a.update(dt, time);
        }

        if(hitEdge) {
            this.formationDir *= -1;
            for(const a of this.aliens) a.mesh.position.z -= 0.8; // Drop down
        }

        // Alien Shooting (Random Fire)
        if(Math.random() < (this.aliens.length / 200) * dt * 60 && this.enemyProjectiles.length < 5) {
            this.fireEnemyShot();
        }

        // Update Projectiles
        this.updateProjectiles(dt);

        // Collision Detection (AABB)
        this.checkCollisions();
    }

    firePlayerShot() {
        if(this.projectiles.find(p => p.active)) return; // One at a time

        const geo = new THREE.BoxGeometry(0.1, 0.8, 0.1);
        const mat = new THREE.MeshBasicMaterial({ color: 0x00ffff });
        const mesh = new THREE.Mesh(geo, mat);

        mesh.position.copy(this.player.pos);
        mesh.position.z -= 1; // Start at tip

        this.projectiles.push({ 
            mesh, active: true, vel: new THREE.Vector3(0, 0, -40) 
        });
    }

    fireEnemyShot() {
        if(this.aliens.length === 0) return;

        // Pick random alien from bottom-most column per X
        const candidates = this.aliens.filter(a => true); // Simplified: random pick
        const shooter = candidates[Math.floor(Math.random() * candidates.length)];

        const geo = new THREE.SphereGeometry(0.2, 4, 4);
        const mat = new THREE.MeshBasicMaterial({ color: 0xffaa00 });
        const mesh = new THREE.Mesh(geo, mat);

        mesh.position.copy(shooter.mesh.position);
        mesh.position.z += 0.5;

        this.enemyProjectiles.push({ 
            mesh, active: true, vel: new THREE.Vector3(0, 0, 15) 
        });
    }

    updateProjectiles(dt: number) {
        // Player Projectiles
        for(let i=this.projectiles.length-1; i>=0; i--) {
            const p = this.projectiles[i];
            if(!p.active) continue;

            p.mesh.position.add(p.vel.clone().multiplyScalar(dt));

            if(p.mesh.position.z < -100) {
                p.active = false;
                p.mesh.visible = false;
                this.projectiles.splice(i, 1);
            }
        }

        // Enemy Projectiles
        for(let i=this.enemyProjectiles.length-1; i>=0; i--) {
            const p = this.enemyProjectiles[i];
            if(!p.active) continue;

            p.mesh.position.add(p.vel.clone().multiplyScalar(dt));

            if(p.mesh.position.z > 5) {
                p.active = false;
                p.mesh.visible = false;
                this.enemyProjectiles.splice(i, 1);
            }
        }
    }

    checkCollisions() {
        // Player Bullet vs Alien
        for(const bullet of this.projectiles) {
            if(!bullet.active) continue;

            for(let i=this.aliens.length-1; i>=0; i--) {
                const alien = this.aliens[i];
                const dist = bullet.mesh.position.distanceTo(alien.mesh.position);

                if(dist < 1.0) { // Hit!
                    bullet.active = false;
                    bullet.mesh.visible = false;

                    // Remove Alien
                    alien.mesh.parent?.remove(alien.mesh);
                    this.aliens.splice(i, 1);

                    // VFX & Score
                    this.particles.spawn(
                        alien.mesh.position.x, 
                        alien.mesh.position.y, 
                        alien.mesh.position.z, 
                        0, -5, -2, 
                        1, 1, 1, 
                        24
                    );
                    this.shake.addImpact(0.2);

                    // Score based on type (simplified: +10 per kill)
                    this.score += 10;

                    break; // Bullet gone
                }
            }
        }

        // Enemy Bullet vs Player
        for(const bullet of this.enemyProjectiles) {
            if(!bullet.active) continue;

            const dist = bullet.mesh.position.distanceTo(this.player.pos);
            if(dist < 1.0) {
                bullet.active = false;
                bullet.mesh.visible = false;

                // Player Hit
                this.lives--;
                this.shake.addImpact(0.8);
                this.particles.spawn(
                    this.player.pos.x, 
                    this.player.pos.y, 
                    this.player.pos.z - 1, 
                    0, 5, 2, 
                    0, 1, 1, 
                    40
                );

                if(this.lives <= 0) {
                    // Game Over logic (simplified: reset wave for now)
                    alert(`GAME OVER! Score: ${this.score}`);
                    location.reload();
                }
            }
        }
    }
